#!/usr/local/bin/prhm-node
'use strict';
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const cp=require('node:child_process');
const ACTION='real_market_verified_economics_uat_v1';
const VERSION='1.8.0-host-actions-v2-verified-economics-replay';
const CONFIRMATION='CONFIRM_LEVEL_4_CRITICAL';
const FILES={base:'/opt/prhm-agent-selfmaint/server.js',executor:'/opt/prhm-agent-selfmaint-exec/server.js',plugin:'/home/agent/ssh-mcp-server/src/plugins/hostActionsV2.js',policy:'/opt/prhm-company-control-plane/config/approval-policy.json',v4helper:'/opt/prhm-agent-selfmaint-exec/actions/mcp-candidate-schema-compare-v1.js',helper:'/opt/prhm-agent-selfmaint-exec/actions/real-market-verified-economics-uat-v1.js'};
const EXPECTED=Object.freeze({
 [FILES.base]:'adae6fc8d49c150706f9811af9c2c494c211ba135e1d0548dc3657af5f3e8d00',
 [FILES.executor]:'487efed91b1c6ccf78990276718c6497967d4dbdffa5892a86a85d2a4f8da3ba',
 [FILES.plugin]:'831fc0a3c42b41fd3c494bffedfda50863b74d7e4f31f7ac340b5272b440ed03',
 [FILES.policy]:'33d61df7539f2812f40723022afebe94187d92d597257f957a227bcd2f410d2d',
 [FILES.v4helper]:'68d95f4b63367317e511c0723ef614f374fb816c769f67b72b3c212d478d742c'
});
const HELPER_CONTENT=Buffer.from('','base64').toString('utf8');
const HELPER_SHA='ff5eca545227742d6fd0d4e1d920a083b1d1569943df51c859739ab347f3db55';
function fail(m){throw new Error(m)}
function shaBuffer(b){return crypto.createHash('sha256').update(b).digest('hex')}
function sha(f){return shaBuffer(fs.readFileSync(f))}
function replaceOnce(s,a,b,l){const i=s.indexOf(a);if(i<0)fail('anchor_missing:'+l);if(s.indexOf(a,i+1)>=0)fail('anchor_not_unique:'+l);return s.slice(0,i)+b+s.slice(i+a.length)}
function exec(f,args,opt={}){const r=cp.spawnSync(f,args,{encoding:'utf8',maxBuffer:4*1024*1024,...opt});if(r.error)fail('exec_error:'+f+':'+r.error.message);if(r.status!==0)fail('exec_failed:'+f+':'+r.status+':'+String(r.stderr||'').slice(-1600));return r}
function baseline(){for(const [f,x] of Object.entries(EXPECTED)){if(!fs.existsSync(f))fail('missing:'+f);const a=sha(f);if(a!==x)fail('sha_mismatch:'+f+':'+a+':'+x)}if(fs.existsSync(FILES.helper))fail('helper_already_exists')}
function patchBase(s){return replaceOnce(s,`  real_market_shadow_uat_v1: { operation: 'host_action.real_market_shadow_uat_v1', rollback: 'host-action-v2:real-market-shadow-uat-v1:temporary-decision-cleanup' }
});`,`  real_market_shadow_uat_v1: { operation: 'host_action.real_market_shadow_uat_v1', rollback: 'host-action-v2:real-market-shadow-uat-v1:temporary-decision-cleanup' },
  real_market_verified_economics_uat_v1: { operation: 'host_action.real_market_verified_economics_uat_v1', rollback: 'host-action-v2:real-market-verified-economics-uat-v1:temporary-facts-decision-cleanup' }
});`,'base_spec')}
function positiveApplyBlock(){return `const REAL_MARKET_VERIFIED_ECONOMICS_UAT_HELPER='/opt/prhm-agent-selfmaint-exec/actions/real-market-verified-economics-uat-v1.js';
const REAL_MARKET_VERIFIED_ECONOMICS_UAT_RESULT='/var/lib/prhm-agent-selfmaint-exec/real-market-verified-economics-uat-v1/latest.json';
function applyRealMarketVerifiedEconomicsUatV1(){
  if(!fs.existsSync(REAL_MARKET_VERIFIED_ECONOMICS_UAT_HELPER))throw new Error('real_market_verified_economics_uat_helper_missing');
  try{if(fs.existsSync(REAL_MARKET_VERIFIED_ECONOMICS_UAT_RESULT))fs.unlinkSync(REAL_MARKET_VERIFIED_ECONOMICS_UAT_RESULT)}catch{}
  const unit='prhm-real-market-verified-economics-uat-v1-'+Date.now();
  const args=['--wait','--unit='+unit,'--property=Type=oneshot','--property=UMask=0077','--property=NoNewPrivileges=true','--property=PrivateTmp=true','--property=ProtectSystem=full','--property=ProtectHome=read-only','--property=RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6','--property=ReadWritePaths=/var/lib/prhm-agent-selfmaint-exec /run/prhm-p0-shadow-worker','--setenv=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','/usr/local/bin/prhm-node',REAL_MARKET_VERIFIED_ECONOMICS_UAT_HELPER];
  cp.execFileSync('/usr/bin/systemd-run',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:240000});
  if(!fs.existsSync(REAL_MARKET_VERIFIED_ECONOMICS_UAT_RESULT))throw new Error('real_market_verified_economics_uat_result_missing');
  const result=readJson(REAL_MARKET_VERIFIED_ECONOMICS_UAT_RESULT);
  if(result.ok!==true||result.action!=='real_market_verified_economics_uat_v1'||result.schema_version!=='prhm.host-action-result.v1'||result.mode!=='historical_real_market_replay'||result.decision!=='SEND_NOW'||result.reason!=='profitable'||Number(result.final_bid)!==800000||Number(result.net_profit)!==569100||result.cleanup_verified!==true||result.fact_residue!==false||result.uat_decision_residue!==false||result.resolved_economics_count!==9||result.required_economics_complete!==true||result.provenance_verified!==true||result.worker_filtered_to_opportunity!==true||result.auto_send_allowed!==false||result.outbox_write!==false||result.bid_write!==false||result.telegram_write!==false||result.business_mutation!==false||result.p0_live!==false||result.proposal_send!==false||result.bid_send!==false)throw new Error('real_market_verified_economics_uat_result_invalid');
  return result;
}
`}
function patchExecutor(s){s=replaceOnce(s,`  real_market_shadow_uat_v1:{operation:'host_action.real_market_shadow_uat_v1',kind:'real_market_shadow_uat_v1'}
});`,`  real_market_shadow_uat_v1:{operation:'host_action.real_market_shadow_uat_v1',kind:'real_market_shadow_uat_v1'},
  real_market_verified_economics_uat_v1:{operation:'host_action.real_market_verified_economics_uat_v1',kind:'real_market_verified_economics_uat_v1'}
});`,'executor_spec');s=replaceOnce(s,'function verifyProcessSandboxV2(){',positiveApplyBlock()+'function verifyProcessSandboxV2(){','executor_apply_function');s=replaceOnce(s,"if(action==='real_market_shadow_uat_v1')return applyRealMarketShadowUatV1();verifyHostActionV2Dependencies(action);","if(action==='real_market_shadow_uat_v1')return applyRealMarketShadowUatV1();if(action==='real_market_verified_economics_uat_v1')return applyRealMarketVerifiedEconomicsUatV1();verifyHostActionV2Dependencies(action);",'executor_dispatch');s=replaceOnce(s,"version: '1.7.1-host-actions-v2-real-market-shadow-uat-validator'","version: '1.8.0-host-actions-v2-verified-economics-replay'",'executor_version');return s}
function patchPlugin(s){s=replaceOnce(s,"'real_market_shadow_uat_v1']);","'real_market_shadow_uat_v1','real_market_verified_economics_uat_v1']);",'plugin_enum');return s.replace('the fixed no-send real-market Shadow UAT.','the fixed no-send real-market Shadow UAT, and the fixed verified-economics historical replay UAT.')}
function patchPolicy(s){const p=JSON.parse(s);if(p.operations?.['host_action.real_market_verified_economics_uat_v1'])fail('policy_operation_already_present');p.operations['host_action.real_market_verified_economics_uat_v1']={level:4};if(!Array.isArray(p.typed_scopes))fail('policy_typed_scopes_missing');if(p.typed_scopes.some(x=>x&&x.action===ACTION))fail('policy_scope_already_present');p.typed_scopes.push({tool:'host_action_v2_apply',project:'control_plane',environment:'production',action:ACTION,risk:'critical',operation:'host_action.real_market_verified_economics_uat_v1',principals:[{principal_id:'mohammad',roles:['mcp-operator']}]});p.version='2026-08-15.3-verified-economics-replay-v1';return JSON.stringify(p,null,2)+String.fromCharCode(10)}
function patchV4(s,pluginSha){return replaceOnce(s,"const EXPECTED_POSTINSTALL_PLUGIN_SHA='831fc0a3c42b41fd3c494bffedfda50863b74d7e4f31f7ac340b5272b440ed03';",`const EXPECTED_POSTINSTALL_PLUGIN_SHA='${pluginSha}';`,'v4_plugin_sha')}
function syntax(label,s,module=false){const f='/tmp/prhm-v8-'+label+'-'+process.pid+(module?'.mjs':'.js');try{fs.writeFileSync(f,s,{mode:0o700});exec('/usr/local/bin/prhm-node',['--check',f])}finally{try{fs.unlinkSync(f)}catch{}}}
function helperPreflight(){const f='/tmp/prhm-v8-helper-'+process.pid+'.js';try{fs.writeFileSync(f,HELPER_CONTENT,{mode:0o700});return JSON.parse(exec('/usr/local/bin/prhm-node',[f,'--preflight-only'],{timeout:120000}).stdout.trim())}finally{try{fs.unlinkSync(f)}catch{}}}
function atomic(file,content,mode){const t=file+'.v8-'+process.pid+'.tmp';fs.writeFileSync(t,content,{mode});fs.chmodSync(t,mode);fs.renameSync(t,file)}
function systemctl(args){exec('/usr/bin/systemctl',args,{timeout:60000})}
function unixHealth(){for(let i=0;i<50;i++){const r=cp.spawnSync('/usr/bin/curl',['-fsS','--max-time','2','--unix-socket','/run/prhm-agent-selfmaint-exec/exec.sock','http://localhost/health'],{encoding:'utf8'});if(r.status===0){try{const x=JSON.parse(r.stdout);if(x.ok===true&&x.version===VERSION)return x}catch{}}Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,200)}fail('executor_health_not_ready')}
function mcpHealth(){for(let i=0;i<50;i++){const r=cp.spawnSync('/usr/bin/curl',['-fsS','--max-time','2','http://127.0.0.1:8123/health'],{encoding:'utf8'});if(r.status===0){try{const x=JSON.parse(r.stdout);if(x.ok===true)return x}catch{}}Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,200)}fail('mcp_health_not_ready')}
function approvalHealth(){for(let i=0;i<50;i++){const r=cp.spawnSync('/usr/bin/curl',['-fsS','--max-time','2','http://127.0.0.1:18133/health'],{encoding:'utf8'});if(r.status===0){try{const x=JSON.parse(r.stdout);if(x.ok===true&&x.policy_version==='2026-08-15.3-verified-economics-replay-v1')return x}catch{}}Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,200)}fail('approval_health_policy_not_ready')}
function main(){
  const a=process.argv.slice(2);
  if(a.length>1||(a.length===1&&a[0]!=='--preflight-only'))fail('unexpected_arguments');
  if(process.getuid&&process.getuid()!==0)fail('must_run_as_root');
  baseline();
  const original={
    base:fs.readFileSync(FILES.base,'utf8'),
    executor:fs.readFileSync(FILES.executor,'utf8'),
    plugin:fs.readFileSync(FILES.plugin,'utf8'),
    policy:fs.readFileSync(FILES.policy,'utf8'),
    v4helper:fs.readFileSync(FILES.v4helper,'utf8')
  };
  const candidate={
    base:patchBase(original.base),
    executor:patchExecutor(original.executor),
    plugin:patchPlugin(original.plugin),
    policy:patchPolicy(original.policy),
    v4helper:null
  };
  const pluginSha=shaBuffer(Buffer.from(candidate.plugin));
  candidate.v4helper=patchV4(original.v4helper,pluginSha);
  syntax('base',candidate.base);
  syntax('executor',candidate.executor);
  syntax('plugin',candidate.plugin,true);
  JSON.parse(candidate.policy);
  syntax('v4helper',candidate.v4helper);
  syntax('helper',HELPER_CONTENT);
  const hp=helperPreflight();
  if(hp.ok!==true||hp.preflight_only!==true||hp.action!==ACTION||hp.expected?.decision!=='SEND_NOW'||hp.database_mutation!==false||hp.business_mutation!==false||hp.p0_live!==false)fail('helper_preflight_invalid:'+JSON.stringify(hp));
  const hashes={base:shaBuffer(Buffer.from(candidate.base)),executor:shaBuffer(Buffer.from(candidate.executor)),plugin:pluginSha,policy:shaBuffer(Buffer.from(candidate.policy)),v4helper:shaBuffer(Buffer.from(candidate.v4helper)),helper:HELPER_SHA};
  if(a[0]==='--preflight-only'){
    console.log(JSON.stringify({ok:true,schema_version:'prhm.host-action-bootstrap-preflight.v1',preflight_only:true,action:ACTION,current_hashes:EXPECTED,candidate_hashes:hashes,target_version:VERSION,helper_preflight:hp,uat_executed:false,database_mutation:false,business_mutation:false,p0_live:false,proposal_send:false,bid_send:false,production_mutation:false}));
    return;
  }
  const stamp=new Date().toISOString().replace(/[-:TZ.]/g,'').slice(0,14);
  const backupDir='/var/backups/prhm-host-actions-v8-verified-economics-replay-'+stamp;
  fs.mkdirSync(backupDir,{recursive:true,mode:0o700});
  for(const k of ['base','executor','plugin','policy','v4helper']){
    const d=path.join(backupDir,k+'-'+path.basename(FILES[k])+'.bak');
    fs.copyFileSync(FILES[k],d,fs.constants.COPYFILE_EXCL);
    fs.chmodSync(d,0o600);
  }
  const changed=[];
  let ok=false;
  try{
    for(const k of ['base','executor','plugin','policy','v4helper']){
      atomic(FILES[k],candidate[k],k==='policy'?0o600:0o755);
      changed.push(k);
    }
    fs.mkdirSync(path.dirname(FILES.helper),{recursive:true,mode:0o755});
    atomic(FILES.helper,HELPER_CONTENT,0o755);
    changed.push('helper');
    systemctl(['restart','prhm-company-approval.service']);
    systemctl(['restart','prhm-agent-selfmaint.service']);
    systemctl(['restart','prhm-agent-selfmaint-exec.service']);
    systemctl(['restart','prhm-agent-mcp.service']);
    const approval=approvalHealth();
    const h=unixHealth();
    const m=mcpHealth();
    if(sha(FILES.helper)!==HELPER_SHA)fail('helper_sha_postverify_failed');
    const p=JSON.parse(fs.readFileSync(FILES.policy,'utf8'));
    if(p.operations?.['host_action.real_market_verified_economics_uat_v1']?.level!==4)fail('policy_level_postverify_failed');
    if(!p.typed_scopes.some(x=>x&&x.action===ACTION&&x.risk==='critical'))fail('policy_scope_postverify_failed');
    const post=helperPreflight();
    if(post.ok!==true||post.preflight_only!==true)fail('post_helper_preflight_failed');
    ok=true;
    console.log(JSON.stringify({ok:true,schema_version:'prhm.host-action-install-result.v1',installed:true,version:VERSION,action:ACTION,helper_sha256:HELPER_SHA,mcp_plugin_sha256:pluginSha,approval_policy_version:p.version,helper_preflight:post,uat_executed:false,database_mutation:false,business_mutation:false,p0_live:false,proposal_send:false,bid_send:false,backup_dir:backupDir,health:{approval,executor:h,mcp:m}}));
  }finally{
    if(!ok){
      for(const k of ['v4helper','policy','plugin','executor','base']){
        if(changed.includes(k)){
          const bak=path.join(backupDir,k+'-'+path.basename(FILES[k])+'.bak');
          fs.copyFileSync(bak,FILES[k]);
          fs.chmodSync(FILES[k],k==='policy'?0o600:0o755);
        }
      }
      if(changed.includes('helper')){try{fs.unlinkSync(FILES.helper)}catch{}}
      try{
        systemctl(['restart','prhm-company-approval.service']);
        systemctl(['restart','prhm-agent-selfmaint.service']);
        systemctl(['restart','prhm-agent-selfmaint-exec.service']);
        systemctl(['restart','prhm-agent-mcp.service']);
      }catch{}
      for(const [file,expected] of Object.entries(EXPECTED))if(sha(file)!==expected)fail('rollback_incomplete:'+file);
    }
  }
}
try{main()}catch(e){process.stderr.write(String(e&&e.stack||e)+String.fromCharCode(10));process.exit(1)}
